    """统计采样点 base+k*D（k 为非负 int）落在半开区间 [lo, hi) 的个数。"""
    if hi <= lo:
        return 0
    first = lo - base
    k0 = (first + d - 1) // d if first > 0 else first // d
    if k0 < 0:
        k0 = 0
    last = hi - 1 - base
    if last < 0:
        return 0
    k1 = last // d
    return k1 - k0 + 1 if k1 >= k0 else 0

