def _dilated_span_count(base, lo, hi, d):
    """统计采样点 base+k*D（k 为非负 int）落在半开区间 [lo, hi) 的个数。

    调用方保证 hi <= base+(K-1)*D+1，故上界自动不超过 K-1。
    """
    if hi <= lo:
        return 0
    k_lo = -((-(lo - base)) // d)  # ceil((lo-base)/D)
    if k_lo < 0:
        k_lo = 0
    k_hi = (hi - 1 - base) // d    # floor((hi-1-base)/D)
    if k_hi < k_lo:
        return 0
    return k_hi - k_lo + 1

